	/**
	 * Builds {@code Slice(limit=innerLimit, Order(?o asc, Slice(limit=outerFirstLimit, Projection(?s ?o))))} — a
	 * wrapper stack no parsed query produces (two slices around one order): the algebra the umbrella plan's "a flat
	 * record cannot represent Slice(Order(Slice(…)))" refers to.
	 */
	private TupleExpr sliceOrderSlice(long innerSliceLimit, long outerSliceLimit) {
		TupleExpr parsed = QueryParserUtil
				.parseTupleQuery(QueryLanguage.SPARQL, "SELECT ?s ?o WHERE { ?s <" + EX + "p> ?o }", null)
				.getTupleExpr();
		TupleExpr projection = parsed instanceof QueryRoot ? ((QueryRoot) parsed).getArg() : parsed;
		projection = projection.clone();
		Slice innerSlice = new Slice(projection);
		innerSlice.setLimit(innerSliceLimit);
		Order order = new Order(innerSlice);
		order.addElement(new OrderElem(new Var("o"), true));
		Slice outerSlice = new Slice(order);
		outerSlice.setLimit(outerSliceLimit);
		return new QueryRoot(outerSlice);
	}

	private List<String> evaluate(TupleExpr algebra) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailConnection sail = conn.getSailConnection();
			List<String> rows = new ArrayList<>();
			try (CloseableIteration<? extends BindingSet> iteration = sail.evaluate(algebra, new SimpleDataset(),
					EmptyBindingSet.getInstance(), true)) {
				while (iteration.hasNext()) {
					BindingSet bs = iteration.next();
					rows.add(bs.getValue("o") == null ? "unbound" : bs.getValue("o").stringValue());
				}
			}
			return rows;
		}
	}

